public static void main(String[] args){
    Scanner sc = new Scanner(System.in);

    final int N = sc.nextInt();
    int[] Qn = new int[N];
    int[] An = new int[N];
    int[] Bn = new int[N];

    for(int i = 0; i < N; i++){
      Qn[i] = sc.nextInt();
    }
    for(int i = 0; i < N; i++){
      An[i] = sc.nextInt();
    }
    for(int i = 0; i < N; i++){
      Bn[i] = sc.nextInt();
    }

    int loopCnt = Integer.MAX_VALUE;
    for(int i = 0; i < N; i++){
      if(An[i] > 0) {
        loopCnt = Math.min(loopCnt, Qn[i] / An[i]);
      }
    }

    int maxServings = 0;
    for(int i = 0; i <= loopCnt; i++){
      int b_min = Integer.MAX_VALUE;
      for(int j = 0; j < N; j++){
        if(Bn[j] > 0) {
          b_min = Math.min(b_min, (Qn[j] - i * An[j]) / Bn[j]);
        }
      }
      maxServings = Math.max(maxServings, i + b_min);
    }

    System.out.println(maxServings);
}
